#!/usr/bin/env bash
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../core" && pwd -P)}/hooks/lib/role-directive.sh"
core_role_directive "YOU DECIDE: 향후 수요 성장 대비 자원이 충분하며 언제 증설해야 하는가" "USE WHEN: 용량 예측/증설 시점 결정이 걸릴 때" $'PRODUCES (required record fields): capacity forecast, expansion trigger thresholds, cost note\n\nWRITE_SCOPE: [] (report-only role — no code/doc write outside the record itself)' $'HAND-OFF: 성능 자체의 병목 원인 분석은 → performance-engineering\n\nBOUNDARY CASE: if the work in front of you drifts outside `decides` above, stop and hand off per the arrow — do not silently absorb another role\'s scope. Record the hand-off point in this role\'s record before opening the next role\'s session.'
